//! The static dictionary (RFC 7932 §8, Appendix A) and its 121 word transforms (Appendix B).
//!
//! `dictionary.bin` is generated by `gen_dictionary.py` from the RFC's hex dump (length,
//! CRC-32 and SHA-256 checked there).

use crate::{Error, Result};

pub(crate) static DICT: &[u8; 122_784] = include_bytes!("dictionary.bin");

/// log2 of the number of words of each length (0 below 4).
pub(crate) const NDBITS: [u8; 25] = [
    0, 0, 0, 0, 10, 10, 11, 11, 10, 10, 10, 10, 10, 9, 9, 8, 7, 7, 8, 7, 7, 6, 6, 5, 5,
];

/// Offset of the first word of each length.
const DOFFSET: [u32; 25] = {
    let mut o = [0u32; 25];
    let mut len = 0;
    while len < 24 {
        let words = if len < 4 { 0 } else { 1u32 << NDBITS[len] };
        o[len + 1] = o[len] + len as u32 * words;
        len += 1;
    }
    o
};

const _: () = assert!(DOFFSET[24] as usize + 24 * (1 << NDBITS[24]) == DICT.len());

/// The elementary transform of a word transform.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Op {
    Identity,
    FermentFirst,
    FermentAll,
    OmitFirst(u8),
    OmitLast(u8),
}

use Op::*;

