/// Upper-cases one UTF-8-ish character at the start of `w` the way §8 says; returns its length.
fn ferment(w: &mut [u8]) -> usize {
    let Some(&c) = w.first() else { return 0 };
    if c < 192 {
        if c.is_ascii_lowercase() {
            w[0] ^= 32;
        }
        1
    } else if c < 224 {
        if let Some(b) = w.get_mut(1) {
            *b ^= 32;
        }
        2
    } else {
        if let Some(b) = w.get_mut(2) {
            *b ^= 5;
        }
        3
    }
}

/// Appends the dictionary word of `len` bytes for `word_id` (the distance past the window)
/// to `out`; at most `room` bytes may be written.
pub(crate) fn push_word(out: &mut Vec<u8>, len: usize, word_id: usize, room: usize) -> Result<()> {
    if !(4..=24).contains(&len) {
        return Err(Error::Invalid("dictionary word length"));
    }
    let bits = NDBITS[len];
    let index = word_id & ((1 << bits) - 1);
    let (prefix, op, suffix) = *TRANSFORMS
        .get(word_id >> bits)
        .ok_or(Error::Invalid("dictionary transform"))?;
    let at = DOFFSET[len] as usize + index * len;
    let mut word = &DICT[at..at + len];
    match op {
        OmitFirst(k) => word = word.get(usize::from(k)..).unwrap_or_default(),
        OmitLast(k) => word = &word[..len.saturating_sub(usize::from(k))],
        _ => {}
    }
    if prefix.len() + word.len() + suffix.len() > room {
        return Err(Error::Invalid("dictionary word past the meta-block"));
    }
    out.extend_from_slice(prefix);
    let start = out.len();
    out.extend_from_slice(word);
    match op {
        FermentFirst => {
            ferment(&mut out[start..]);
        }
        FermentAll => {
            let mut i = start;
            while i < out.len() {
                i += ferment(&mut out[i..]);
            }
        }
        _ => {}
    }
    out.extend_from_slice(suffix);
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// RFC 7932 Appendix C.
    pub(crate) fn crc32(v: &[u8]) -> u32 {
        let mut crc = 0xFFFF_FFFFu32;
        for &b in v {
            let mut c = (crc ^ u32::from(b)) & 0xFF;
            for _ in 0..8 {
                c = if c & 1 != 0 {
                    0xEDB8_8320 ^ (c >> 1)
                } else {
                    c >> 1
                };
            }
            crc = c ^ (crc >> 8);
        }
        crc ^ 0xFFFF_FFFF
    }

    #[test]
    fn dictionary_check_value() {
        assert_eq!(crc32(DICT), 0x5136_CB04);
    }

    /// Appendix B's check: each transform as prefix, 0, its id, suffix, 0.
    #[test]
    fn transforms_check_value() {
        let mut v = Vec::new();
        for &(p, op, s) in &TRANSFORMS {
            v.extend_from_slice(p);
            v.push(0);
            v.push(match op {
                Identity => 0,
                FermentFirst => 1,
                FermentAll => 2,
                OmitFirst(k) => 2 + k,
                OmitLast(k) => 11 + k,
            });
            v.extend_from_slice(s);
            v.push(0);
        }
        assert_eq!(v.len(), 648);
        assert_eq!(crc32(&v), 0x3D96_5F81);
    }

    #[test]
    fn words() {
        let mut out = Vec::new();
        // The first 4-byte word, as is and through a few transforms.
        push_word(&mut out, 4, 0, 64).unwrap();
        assert_eq!(out, b"time");
        out.clear();
        push_word(&mut out, 4, 9 << 10, 64).unwrap();
        assert_eq!(out, b"Time");
        out.clear();
        push_word(&mut out, 4, 73 << 10, 64).unwrap();
        assert_eq!(out, b" the time of the ");
        out.clear();
        push_word(&mut out, 4, 44 << 10, 64).unwrap();
        assert_eq!(out, b"TIME");
        out.clear();
        push_word(&mut out, 4, 54 << 10, 64).unwrap();
        assert_eq!(out, b"");
        assert!(push_word(&mut out, 4, 121 << 10, 64).is_err());
        assert!(push_word(&mut out, 3, 0, 64).is_err());
        assert!(push_word(&mut out, 25, 0, 64).is_err());
        assert!(push_word(&mut out, 4, 5 << 10, 8).is_err());
    }
}
